INSERT INTO "RegisterDefinition" (
  "id", "organisationId", "key", "name", "description", "fieldSchema",
  "isPublished", "sortOrder", "createdAt", "updatedAt"
)
SELECT md5('register-definition:' || key)::uuid, NULL, key, name, description, fields, true, sort_order, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM definitions
ON CONFLICT ("id") DO UPDATE SET
  "name" = EXCLUDED."name",
  "description" = EXCLUDED."description",
  "fieldSchema" = EXCLUDED."fieldSchema",
  "isPublished" = true,
  "sortOrder" = EXCLUDED."sortOrder",
  "updatedAt" = CURRENT_TIMESTAMP;
